package main
import("encoding/json";"flag";"fmt";"os";"path/filepath";"time";"github.com/zeuvoryx/zeuvoryx/adaptive")
func main(){out:=flag.String("out","lab-results/adaptive-report-50m.json","local report");flag.Parse();start:=time.Now();r,e:=adaptive.RunLab50(adaptive.Lab50Train,adaptive.Lab50Validation,adaptive.Lab50Nominal,adaptive.Lab50Shift,func(p string,n int){fmt.Println(p,n)});if e!=nil{panic(e)};payload:=struct{adaptive.Lab50Report;Families [10]string;ElapsedMS int64;Deployment string}{r,adaptive.LabFamilies,time.Since(start).Milliseconds(),"Candidate not deployed; real-world validation required"};b,e:=json.MarshalIndent(payload,"","  ");if e!=nil{panic(e)};if e=os.MkdirAll(filepath.Dir(*out),0755);e!=nil{panic(e)};if e=os.WriteFile(*out,b,0600);e!=nil{panic(e)};fmt.Printf("nominal baseline FPR %.6f FNR %.6f candidate FPR %.6f FNR %.6f\n",r.NominalTest.Baseline.FPR(),r.NominalTest.Baseline.FNR(),r.NominalTest.Candidate.FPR(),r.NominalTest.Candidate.FNR());fmt.Printf("shift baseline FPR %.6f FNR %.6f candidate FPR %.6f FNR %.6f\n",r.ShiftTest.Baseline.FPR(),r.ShiftTest.Baseline.FNR(),r.ShiftTest.Candidate.FPR(),r.ShiftTest.Candidate.FNR());fmt.Printf("accepted %v; elapsed %s\n",r.Accepted,time.Since(start))}
